  if(kind==="request")return {...base,cycleId,title:text("title"),description:text("description"),requirementIds:many("requirementIds"),findingIds:many("findingIds"),obligationIds:many("obligationIds"),owner:text("owner"),dueDate:text("dueDate"),status:text("status"),submissionIds:many("submissionIds"),reviewNote:text("reviewNote")};
